CREATE TABLE ticket_ratings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), ticket_id uuid NOT NULL REFERENCES tickets(id), requester_user_id uuid NOT NULL REFERENCES users(id), score smallint NOT NULL CHECK(score BETWEEN 1 AND 5), comment text CHECK(char_length(comment)<=2000), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(ticket_id,requester_user_id)); ALTER TABLE ticket_ratings ENABLE ROW LEVEL SECURITY; CREATE POLICY ratings_tenant ON ticket_ratings USING(organization_id=app.current_organization_id()) WITH CHECK(organization_id=app.current_organization_id()); GRANT SELECT,INSERT ON ticket_ratings TO jupiter_app;
